import {project} from './geo.js';
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),svg=$('#europe'),world=$('#map-world'),panel=$('.map-panel'),tooltip=$('#map-tooltip');
const points={oslo:project([10.7522,59.9139]),torp:project([10.2586,59.1867]),hovik:project([10.5817,59.9]),pl:project([19.1,52.1]),en:project([-1.3,52.5]),no:project([8.7,62.1])};
let busy=false,selected=null,routeLength=0;
$('#label-no').setAttribute('transform',`translate(${project([12,65])[0]},${project([12,65])[1]})`);$('#label-pl').setAttribute('transform',`translate(${points.pl[0]},${points.pl[1]-6})`);$('#oslo-marker').setAttribute('transform',`translate(${points.oslo})`);
const clock=()=>{$('#clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Oslo',hour:'2-digit',minute:'2-digit'}).format(new Date())};clock();setInterval(clock,30000);
const languageNames={en:'English',pl:'Polski',no:'Norsk'};
function highlight(lang){if(busy)return;$$('[data-lang]').forEach(el=>el.classList.toggle('is-active',el.dataset.lang===lang))}
function localPoint(e){return new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse())}
$$('[data-lang]').forEach(el=>{el.addEventListener('pointerenter',e=>{highlight(el.dataset.lang);if(el.classList.contains('land')&&e.pointerType==='mouse'){tooltip.firstElementChild.textContent=languageNames[el.dataset.lang]+' · Start your journey';tooltip.classList.add('visible')}});el.addEventListener('pointerleave',()=>{highlight(null);tooltip.classList.remove('visible')});el.addEventListener('focus',()=>highlight(el.dataset.lang));el.addEventListener('blur',()=>highlight(null));el.addEventListener('click',e=>{const lang=el.dataset.lang;const p=el.classList.contains('land')?localPoint(e):null;journey(lang,p?[p.x,p.y]:points[lang])});if(el.tagName.toLowerCase()==='path')el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();journey(el.dataset.lang,points[el.dataset.lang])}})});
panel.addEventListener('pointermove',e=>{const b=panel.getBoundingClientRect();tooltip.style.transform=`translate(${Math.min(e.clientX-b.left+17,b.width-230)}px,${e.clientY-b.top-48}px)`});
function go(){location.assign('/'+selected+'/')}
$('#skip').addEventListener('click',go);
function status(step,text){$('#journey-step').textContent=step;$('#journey-text').textContent=text}
function tween(duration,update){return new Promise(resolve=>{const start=performance.now();function tick(t){const p=Math.min(1,(t-start)/duration);update(p);if(p<1)requestAnimationFrame(tick);else resolve()}requestAnimationFrame(tick)})}
const ease=p=>p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;
function cameraAt(p,zoom){world.setAttribute('transform',`translate(${500-p[0]*zoom} ${390-p[1]*zoom}) scale(${zoom})`);$$('.map-label,.sea-label').forEach(el=>el.style.opacity=Math.max(0,1-(zoom-1)/1.4));$('#oslo-marker').setAttribute('transform',`translate(${points.oslo}) scale(${1/zoom})`)}
async function moveCamera(center,zoom,duration){await tween(duration,p=>{p=ease(p);const z=1+(zoom-1)*p;cameraAt([500+(center[0]-500)*p,390+(center[1]-390)*p],z)})}
function curve(a,b,isFlight){const dx=b[0]-a[0],dy=b[1]-a[1],lift=isFlight?Math.min(130,Math.hypot(dx,dy)*.38):Math.min(18,Math.hypot(dx,dy)*.15);return `M${a}Q${(a[0]+b[0])/2-lift} ${(a[1]+b[1])/2-lift} ${b}`}
async function travel(a,b,vehicle,duration,flight=true){const route=$('#route'),under=$('#route-under'),icon=$('#'+vehicle),d=curve(a,b,flight);route.setAttribute('d',d);under.setAttribute('d',d);route.style.opacity=1;under.style.opacity=1;routeLength=route.getTotalLength();icon.style.display='block';await tween(duration,p=>{const t=ease(p),distance=routeLength*t,v=route.getPointAtLength(distance),next=route.getPointAtLength(Math.min(routeLength,distance+1)),prev=route.getPointAtLength(Math.max(0,distance-1)),angle=Math.atan2(next.y-prev.y,next.x-prev.x)*180/Math.PI+90;icon.setAttribute('transform',`translate(${v.x} ${v.y}) rotate(${angle}) scale(${flight?1:.6})`);route.style.strokeDasharray=`${distance} ${routeLength}`;if(flight)icon.style.opacity=Math.min(1,p*8,(1-p)*10+.15)});icon.style.display='none'}
async function journey(lang,start){if(busy)return;selected=lang;if(matchMedia('(prefers-reduced-motion: reduce)').matches){go();return}highlight(lang);busy=true;document.body.classList.add('is-traveling');$('.language-picker').setAttribute('aria-disabled','true');$$('.language-option').forEach(el=>el.disabled=true);tooltip.classList.remove('visible');$('#journey-status').classList.add('is-visible');
if(lang==='no'){status('01 / A LITTLE CLOSER','Driving to Høvik.');await travel(start,points.hovik,'car',2000,false);await moveCamera(points.hovik,2.8,650);await arrive(points.hovik)}else{status('01 / NORTHBOUND','Flying to Sandefjord, Norway.');await travel(start,points.torp,'plane',2200);status('02 / THE LAST STRETCH','Landed. Next stop, Oslo.');await moveCamera(project([10.5,59.55]),4.8,700);await travel(points.torp,points.oslo,'car',1300,false);await arrive(points.oslo)}status('YOU HAVE ARRIVED',languageNames[lang]+'. Welcome.');await tween(500,()=>{});go()}
async function arrive(point){const ring=$('#arrival');ring.setAttribute('transform',`translate(${point})`);await tween(450,p=>{ring.style.opacity=1;ring.firstElementChild.setAttribute('r',3+8*p);ring.firstElementChild.style.opacity=1-p*.5})}
